    const stroke={type:'stroke',layer:old.layer,stage:old.stage,color:old.color,width:old.width,opacity:old.opacity,subphase:old.subphase,part:old.part,objectId:old.objectId,endpoints:old.endpoints,...entry.group?.stroke,id:sourceId};
